//! Brand and Liquid Glass design tokens — single source of truth for the TRAN stack.
//!
//! Platform artifacts (TypeScript, CSS, native stubs) are generated by `tran-tokens-codegen`.

use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;

/// Validates `#RGB`, `#RRGGBB`, or `#RRGGBBAA` hex colors.
pub fn is_valid_hex_color(value: &str) -> bool {
    let hex = value.strip_prefix('#').unwrap_or(value);
    let len = hex.len();
    if len != 3 && len != 6 && len != 8 {
        return false;
    }
    hex.chars().all(|c| c.is_ascii_hexdigit())
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Eq)]
#[serde(transparent)]
pub struct HexColor(pub String);

impl HexColor {
    pub fn new(value: &str) -> Result<Self, String> {
        if is_valid_hex_color(value) {
            Ok(Self(value.to_string()))
        } else {
            Err(format!("invalid hex color: {value}"))
        }
    }
}

